package io.scenariomesh.scheduler; import io.scenariomesh.core.*;import io.scenariomesh.core.Domain.*;import java.time.*;import java.util.*;import java.util.function.*;
public final class DurationAwareScheduler implements Ports.SchedulingStrategy {private final Ports.ExecutionHistoryStore history;private final PriorityQueue<ScenarioTask> q; public DurationAwareScheduler(Ports.ExecutionHistoryStore h){history=h;q=new PriorityQueue<>(Comparator.comparingLong(this::estimate).reversed().thenComparing(t->t.id().value()));}private long estimate(ScenarioTask t){if(t.estimatedDuration()!=null)return t.estimatedDuration().toMillis();return history.durationMillis(t.id()).orElse(0);}public synchronized void load(Collection<ScenarioTask> tasks){q.addAll(tasks);}public synchronized ScenarioTask nextEligible(Predicate<ScenarioTask> eligible){if(q.isEmpty())return null;var skipped=new ArrayList<ScenarioTask>();ScenarioTask selected=null;while(!q.isEmpty()){var t=q.poll();if(eligible.test(t)){selected=t;break;}skipped.add(t);}q.addAll(skipped);return selected;}public synchronized int queued(){return q.size();}}
